import boto3
from typing import Dict, Any, List, Optional
from document_models import ExtractedInvoice

def _get_text(result, blocks_map):
    text = ''
    if 'Relationships' in result:
        for relationship in result['Relationships']:
            if relationship['Type'] == 'CHILD':
                for child_id in relationship['Ids']:
                    word = blocks_map[child_id]
                    if word['BlockType'] == 'WORD':
                        text += word['Text'] + ' '
                    if word['BlockType'] == 'SELECTION_ELEMENT':
                        if word['SelectionStatus'] == 'SELECTED':
                            text += 'X '
    return text

def extract_invoice_fields(image_bytes: bytes) -> ExtractedInvoice:
    client = boto3.client('textract')
    response = client.analyze_document(
        Document={'Bytes': image_bytes},
        FeatureTypes=['FORMS']
    )

    blocks = response['Blocks']
    blocks_map = {block['Id']: block for block in blocks}
    key_value_pairs = {}

    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'KEY' in block['EntityTypes']:
                key_text = _get_text(block, blocks_map)
                value_text = ''
                if 'Relationships' in block:
                    for relationship in block['Relationships']:
                        if relationship['Type'] == 'VALUE':
                            for value_id in relationship['Ids']:
                                value_block = blocks_map[value_id]
                                value_text = _get_text(value_block, blocks_map)
                key_value_pairs[key_text.strip()] = value_text.strip()

    vendor_name: Optional[str] = None
    invoice_date: Optional[str] = None
    total_amount: Optional[float] = None
    line_items: List[Dict[str, Any]] = []

    for key, value in key_value_pairs.items():
        lower_key = key.lower()
        if 'vendor name' in lower_key or 'seller name' in lower_key or 'company' in lower_key:
            vendor_name = value
        elif 'invoice date' in lower_key or 'date' in lower_key:
            invoice_date = value
        elif 'total' in lower_key or 'amount due' in lower_key or 'balance due' in lower_key:
            try:
                cleaned_value = value.replace('$', '').replace(',', '').strip()
                total_amount = float(cleaned_value)
            except ValueError:
                pass

    return ExtractedInvoice(
        vendor_name=vendor_name,
        invoice_date=invoice_date,
        total_amount=total_amount,
        line_items=line_items,
    )

from google.cloud import documentai_v1 as documentai
from google.api_core.client_options import ClientOptions
from typing import Dict, Any, List, Optional
from document_models import ExtractedReceipt

# Replace with your actual project ID, location, and processor ID
PROJECT_ID = 'your-gcp-project-id'
LOCATION = 'us'  # e.g., 'us' or 'eu'
PROCESSOR_ID = 'your-receipt-processor-id'  # e.g., 'receipt-parser-001'

# The full resource name of the processor
# e.g.: projects/project_id/locations/location/processors/processor_id
PROCESSOR_NAME = f'projects/{PROJECT_ID}/locations/{LOCATION}/processors/{PROCESSOR_ID}'

def extract_receipt_fields(image_bytes: bytes) -> ExtractedReceipt:
    client_options = ClientOptions(api_endpoint=f'{LOCATION}-documentai.googleapis.com')
    client = documentai.DocumentProcessorServiceClient(client_options=client_options)

    # Read the file into memory
    raw_document = documentai.RawDocument(
        content=image_bytes,
        mime_type='application/pdf' # or 'image/jpeg', 'image/png'
    )

    # Configure the process request
    request = documentai.ProcessRequest(
        name=PROCESSOR_NAME,
        raw_document=raw_document,
    )

    result = client.process_document(request=request)
    document = result.document

    merchant_name: Optional[str] = None
    tax_amount: Optional[float] = None
    total_amount: Optional[float] = None
    items: List[Dict[str, Any]] = []

    for entity in document.entities:
        if entity.type == 'merchant_name':
            merchant_name = entity.mention_text
        elif entity.type == 'total_amount':
            try:
                total_amount = float(entity.mention_text)
            except ValueError:
                pass
        elif entity.type == 'tax_amount':
            try:
                tax_amount = float(entity.mention_text)
            except ValueError:
                pass
        elif entity.type == 'line_item':
            item_data = {}
            for prop in entity.properties:
                if prop.type == 'description':
                    item_data['description'] = prop.mention_text
                elif prop.type == 'amount':
                    try:
                        item_data['amount'] = float(prop.mention_text)
                    except ValueError:
                        pass
            if item_data:
                items.append(item_data)

    return ExtractedReceipt(
        merchant_name=merchant_name,
        tax_amount=tax_amount,
        total_amount=total_amount,
        items=items
    )
